  `is_running` tinyint(1) DEFAULT NULL COMMENT 'is running(0 no|1 yes)',
  `gmt_updated` datetime(3) NOT NULL,
  PRIMARY KEY (`xid`),
  UNIQUE KEY `unikey_buz_tenant` (`business_key`,`tenant_id`)
